@pytest.mark.parametrize("case", CASES)
def test_case(lit, case):
    mlir = HERE / f"{case}.mlir"
    lit_lines.run(lit, mlir if mlir.is_file() else HERE / f"{case}.test", CASES[case], MAINS)
